all_proposals.code:
def priority(item: float, remaining_capacity: float, bin_capacity: float) -> float:
    leftover = remaining_capacity - item
    bf_norm = -leftover / bin_capacity  # range [-1,0]? Actually leftover >=0, so bf_norm <=0, higher (closer to zero) better.
    size_term = item / bin_capacity  # in [0,1]
    return bf_norm * (1 + size_term)
